// rate-limit — cross-process token bucket via shared memory
// Rate: 10/s, burst: 20

const RATE = 10;
const BURST = 20;
const SHM_NAME = "z_rl_v1";

fn rl_init::() {
    let shm = @shm_create(SHM_NAME, 64);
    let now = @time_ms();
    @shm_write(shm, 0, @bytes(@json_encode({
        "tokens": BURST, "last": now, "rate": RATE, "burst": BURST
    })));
    return shm;
}

fn rl_open::() { return @shm_open_z(SHM_NAME); }

fn rl_state::(shm) {
    return @json_decode(@mem_to_string(@mem_from_bytes(@shm_read(shm, 0, 64))));
}

fn rl_save::(shm, state) {
    let blob = @bytes(@json_encode(state));
    @shm_write(shm, 0, blob);
}

fn rl_refill::(state) {
    let now = @time_ms();
    let elapsed = (now - state["last"]) / 1000.0;
    state["tokens"] = @min(state["burst"], state["tokens"] + elapsed * state["rate"]);
    state["last"] = now;
}

fn rl_take::(shm, n) {
    let state = rl_state(shm);
    rl_refill(state);
    if (state["tokens"] >= n) {
        state["tokens"] -= n;
        rl_save(shm, state);
        return true;
    }
    rl_save(shm, state);
    return false;
}

fn rl_available::(shm) {
    let state = rl_state(shm);
    rl_refill(state);
    rl_save(shm, state);
    return @floor(state["tokens"]);
}

fn version::() { return "1.0.0"; }
